export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tTop = u / g;
  const yTop = (u * u) / (2 * g);
  const tMax = 2 * tTop;
  const t = Math.max(0, Math.min(time, tMax));

  const y = u * t - 0.5 * g * t * t;
  const v = u - g * t;
  const a = -g;
  const Fg = m * g;

  let motionState = "Ready to toss";
  if (t > 0 && t < tTop - 0.05) {
    motionState = "Rising";
  } else if (Math.abs(t - tTop) <= 0.05) {
    motionState = "At the top";
  } else if (t > tTop + 0.05 && t < tMax - 0.02) {
    motionState = "Falling";
  } else if (t >= tMax - 0.02) {
    motionState = "Back at launch height";
  }

  const scaleY = 110;
  const baseY = 320;
  const ballX = 160;
  const ballY = baseY - y * scaleY;

  const objects = [];

  objects.push(...sdk.panel({
    x: 20,
    y: 40,
    w: 280,
    h: 340,
    title: "The motion",
    state: motionState,
    id: "lane.toss"
  }));

  objects.push(sdk.axis("axis.height", {
    x: 80,
    y: baseY,
    length: 220,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  }));

  objects.push(sdk.circle("ball.toss", ballX, ballY, 24, { role: "output" }));

  objects.push(...sdk.vector("vec.v", { x: ballX + 20, y: ballY }, { value: v, direction: "up" }, { scale: 15, minLength: 12, label: "v" }));
  objects.push(...sdk.vector("vec.a", { x: ballX - 25, y: ballY }, { value: a, direction: "up" }, { scale: 15, minLength: 12, label: "a" }));

  objects.push(...sdk.callout(ballX + 50, ballY - 30, [
    `v: ${v.toFixed(2)} m/s`,
    `a: ${a.toFixed(2)} m/s^2`,
    `Fg: ${Fg.toFixed(1)} N`
  ], { id: "callout.toss" }));

  objects.push(...sdk.panel({
    x: 320,
    y: 40,
    w: 300,
    h: 340,
    title: "Velocity over time",
    state: `t = ${t.toFixed(2)} s`,
    id: "lane.vt"
  }));

  const points = sdk.sample((ts) => u - g * ts, 0, t, 20);

  objects.push(sdk.plot("plot.vt", {
    x: 340,
    y: 80,
    w: 260,
    h: 220,
    axes: {
      x: { label: "Time", min: 0, max: 1.8, unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      { label: "v(t)", kind: "line", points: points.map(([ts, vs]) => ({ x: ts, y: vs })) }
    ]
  }));

  objects.push(sdk.text("plot.vt.note", 350, 330, "Slope a = -g", { role: "neutral" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "velocity", value: Number(v.toFixed(2)) },
        { id: "acceleration", value: Number(a.toFixed(2)) },
        { id: "force", value: Number(Fg.toFixed(2)) },
        { id: "motionState", value: motionState }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: tTop,
      apexHeight: yTop,
      height: y,
      velocity: v,
      acceleration: a,
      force: Fg
    }
  };
}
